const pendingCatalogPublications = `-- name: PendingCatalogPublications :many
SELECT p.organization_id, p.project_id, p.service_id, p.manifest_id, p.outcome, p.external_receipt, p.updated_at FROM artifact_catalog_publications p JOIN artifact_catalog_manifests m ON m.organization_id=p.organization_id AND m.project_id=p.project_id AND m.service_id=p.service_id AND m.id=p.manifest_id
JOIN artifact_catalog_uploads u ON u.organization_id=m.organization_id AND u.project_id=m.project_id AND u.service_id=m.service_id AND u.id=m.upload_id
WHERE p.organization_id=$1 AND p.outcome<>'committed' AND u.state<>'deleted' ORDER BY p.updated_at,p.project_id,p.service_id,p.manifest_id LIMIT $2
`

type PendingCatalogPublicationsParams struct {
	OrganizationID tracker.OrganizationID
	Limit          int32
}

func (q *Queries) PendingCatalogPublications(ctx context.Context, arg PendingCatalogPublicationsParams) ([]ArtifactCatalogPublication, error) {
	rows, err := q.db.Query(ctx, pendingCatalogPublications, arg.OrganizationID, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ArtifactCatalogPublication{}
	for rows.Next() {
		var i ArtifactCatalogPublication
		if err := rows.Scan(
			&i.OrganizationID,
			&i.ProjectID,
			&i.ServiceID,
			&i.ManifestID,
			&i.Outcome,
			&i.ExternalReceipt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

